head.script:
scwin.onpageload = function() {
    scwin.form_onLoadCompleted();
}		
scwin.form_onLoadCompleted = function() {
    ft.hide();
    ft2.hide();
    ft3.hide();
    ft4.hide();
};
scwin.trigger1_onclick = function() {
    ft.show();
};
scwin.trigger2_onclick = function() {
    ft2.show();
};
scwin.trigger3_onclick = function() {
    ft3.show();
};
scwin.trigger4_onclick = function() {
    ft4.show();
};
scwin.checkVal1 = function() {
    return WebSquare.wUnit.getDomById('ft').style.display == 'block';
};
scwin.checkVal2 = function() {
    return WebSquare.wUnit.getDomById('ft2').style.display == 'block';
};
scwin.checkVal3 = function() {
    return WebSquare.wUnit.getObjById('ft').getStyle('z-index') == '3999';
};
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();

    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");

    WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
    WebSquare.wUnit.addCommand("pause", "500");

    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger2').click()");
    WebSquare.wUnit.addCommand("pause", "500");

    WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal3()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();
